    fprintf('   - Typically 65537 (must be coprime with φ(n))\n');
    fprintf('   - Verify with gcd(e, φ(n)) == 1\n\n');

    fprintf('4. Calculate private exponent (d = e^(-1) mod φ(n))\n');
    fprintf('   - Use extended Euclidean algorithm\n');
    fprintf('   - Core secret component of private key\n\n');

    fprintf('5. Form keys:\n');
    fprintf('   - Public: (e,n) for encryption\n');
    fprintf('   - Private: (d,n) for decryption\n\n');

    fprintf('KEY CONSIDERATIONS:\n');
    fprintf('- Prime quality: Use strong primes with proper entropy\n');
    fprintf('- Key sizes: 2048-bit minimum recommended\n');
    fprintf('- Verification: Always test encryption/decryption cycle\n\n');

