import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  View,
  StyleSheet,
  PanResponder,
  Dimensions,
  Text,
  Alert,
  ActivityIndicator,
  SafeAreaView,
  TouchableOpacity,
} from 'react-native';
import axios from 'axios';
import { useQuery, useQueryClient } from 'react-query';

// Constants
const SCREEN_WIDTH = Dimensions.get('window').width;
const SCREEN_HEIGHT = Dimensions.get('window').height;
const CANVAS_WIDTH = SCREEN_WIDTH - 40;
const CANVAS_HEIGHT = SCREEN_HEIGHT - 250;
const MAX_COORDINATE = 2160;
const BATCH_SIZE = 10;
const POINT_RADIUS = 10;
const MIN_PATH_LENGTH = 5;

const App = () => {
  const [points, setPoints] = useState([]);
  const [currentBatch, setCurrentBatch] = useState([]);
  const [currentBatchIndex, setCurrentBatchIndex] = useState(0);
  const [userPath, setUserPath] = useState([]);
  const [completedPaths, setCompletedPaths] = useState([]);
  const [isDrawing, setIsDrawing] = useState(false);

  // API call to fetch coordinates
  const fetchPoints = useCallback(async () => {
    try {
      const response = await axios.get('YOUR_API_ENDPOINT');
      const data = response.data;

      if (Array.isArray(data)) {
        setPoints(data);
        // Initialize first batch
        setCurrentBatch(data.slice(0, BATCH_SIZE));
      }
    } catch (error) {
      console.error('API Error:', error);
      // Fallback mock data
      const mockData = Array.from({ length: 30 }, (_, i) => ({
        x: Math.floor(Math.random() * MAX_COORDINATE),
        y: Math.floor(Math.random() * MAX_COORDINATE),
      }));
      setPoints(mockData);
      setCurrentBatch(mockData.slice(0, BATCH_SIZE));
    }
  }, []);

  useEffect(() => {
    fetchPoints();
  }, [fetchPoints]);

  // Update current batch when batch index changes
  useEffect(() => {
    if (points.length > 0) {
      const start = currentBatchIndex * BATCH_SIZE;
      const end = start + BATCH_SIZE;
      setCurrentBatch(points.slice(start, end));
    }
  }, [currentBatchIndex, points]);

  // Convert API coordinates to screen coordinates
  const convertCoordinate = (coord, isX) => {
    const padding = 20;
    const range = isX ? CANVAS_WIDTH : CANVAS_HEIGHT;
    return padding + (coord / MAX_COORDINATE) * (range - 2 * padding);
  };

  // Handle touch drawing
  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: (e) => {
        setIsDrawing(true);
        setUserPath([{
          x: e.nativeEvent.locationX,
          y: e.nativeEvent.locationY
        }]);
      },
      onPanResponderMove: (e) => {
        if (isDrawing) {
          setUserPath(prev => [...prev, {
            x: e.nativeEvent.locationX,
            y: e.nativeEvent.locationY
          }]);
        }
      },
      onPanResponderRelease: () => {
        setIsDrawing(false);
        handleBatchComplete();
      },
    })
  ).current;

  const handleBatchComplete = () => {
    // Save completed path
    setCompletedPaths(prev => [...prev, {
      batchIndex: currentBatchIndex,
      path: [...userPath]
    }]);

    setUserPath([]);

    // Move to next batch or finish
    const nextIndex = currentBatchIndex + 1;
    if (nextIndex * BATCH_SIZE < points.length) {
      setCurrentBatchIndex(nextIndex);
    } else {
      // All batches complete
      setCurrentBatch([]); // Erase final points
      Alert.alert('Complete!', 'All points connected. Final curve remains.');
    }
  };

  const renderPoints = () => {
    return currentBatch.map((point, i) => {
      const screenX = convertCoordinate(point.x, true);
      const screenY = convertCoordinate(point.y, false);
      const pointNumber = currentBatchIndex * BATCH_SIZE + i + 1;

      return (
        <View
          key={`point-${pointNumber}`}
          style={[
            styles.point,
            {
              left: screenX - POINT_RADIUS,
              top: screenY - POINT_RADIUS,
            },
          ]}
        >
          <Text style={styles.pointLabel}>{pointNumber}</Text>
        </View>
      );
    });
  };

  const renderPaths = () => {
    return (
      <>
        {/* Completed paths */}
        {completedPaths.map((completed, i) => (
          completed.path.slice(1).map((point, j) => {
            const prev = completed.path[j];
            return (
              <View
                key={`completed-${i}-${j}`}
                style={[
                  styles.pathSegment,
                  {
                    left: Math.min(prev.x, point.x),
                    top: Math.min(prev.y, point.y),
                    width: Math.abs(point.x - prev.x),
                    height: Math.abs(point.y - prev.y),
                    borderLeftWidth: point.x !== prev.x ? 2 : 0,
                    borderTopWidth: point.y !== prev.y ? 2 : 0,
                  },
                ]}
              />
            );
          })
        ))}

        {/* Current path */}
        {userPath.slice(1).map((point, i) => {
          const prev = userPath[i];
          return (
            <View
              key={`current-${i}`}
              style={[
                styles.currentPathSegment,
                {
                  left: Math.min(prev.x, point.x),
                  top: Math.min(prev.y, point.y),
                  width: Math.abs(point.x - prev.x),
                  height: Math.abs(point.y - prev.y),
                  borderLeftWidth: point.x !== prev.x ? 2 : 0,
                  borderTopWidth: point.y !== prev.y ? 2 : 0,
                },
              ]}
            />
          );
        })}
      </>
    );
  };

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.title}>Connect the Points</Text>

      <View style={styles.canvas} {...panResponder.panHandlers}>
        {renderPaths()}
        {renderPoints()}
      </View>

      <Text style={styles.instructions}>
        {currentBatch.length > 0 
          ? `Connect points ${currentBatchIndex * BATCH_SIZE + 1} to ${currentBatchIndex * BATCH_SIZE + currentBatch.length}`
          : 'All points connected!'
        }
      </Text>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: 'center',
    paddingTop: 50,
  },
  title: {
    fontSize: 24,
    fontWeight: 'bold',
    marginBottom: 20,
  },
  canvas: {
    width: CANVAS_WIDTH,
    height: CANVAS_HEIGHT,
    backgroundColor: 'white',
    borderRadius: 10,
    position: 'relative',
    marginBottom: 20,
  },
  point: {
    position: 'absolute',
    width: POINT_RADIUS * 2,
    height: POINT_RADIUS * 2,
    borderRadius: POINT_RADIUS,
    backgroundColor: 'blue',
    justifyContent: 'center',
    alignItems: 'center',
  },
  pointLabel: {
    color: 'white',
    fontSize: 10,
  },
  pathSegment: {
    position: 'absolute',
    borderColor: 'green',
  },
  currentPathSegment: {
    position: 'absolute',
    borderColor: 'orange',
  },
  instructions: {
    fontSize: 18,
  },
});

export default App;
```

## Key Features:

1. **API Integration**: 
   - Uses axios to fetch coordinate data
   - Includes error handling with fallback mock data
   - Validates API response structure

2. **Batch Management**:
   - Shows points in batches of 10
   - Automatically transitions between batches
   - Erases previous points while retaining drawings

3. **Drawing System**:
   - Uses PanResponder for touch drawing
   - Tracks user path and validates completion
   - When all batches complete, erases final points but keeps curves

4. **Coordinate Conversion**:
   - Converts API coordinates (0-2160) to screen coordinates
   - Applies proper padding and scaling

5. **Visual Elements**:
   - Points shown as blue circles with numbers
   - Current drawing in orange
   - Completed paths in green

